async function e(e,t){let n=await fetch(e,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify(t)});if(!n.ok)throw Error(`${e} responded ${n.status}`);return n.json()}async function t(t,n,r){try{return{available:!0,...await e(`/api/compare-proof`,{beforeUrl:t,afterUrl:n,category:r})}}catch(e){return console.warn(`compare-proof unavailable, using fallback`,e),{available:!1,summary:`The AI service is offline, so the photos were not compared. Rely on resident attestations and the reviewer.`,flags:n?[]:[`No after-photo uploaded`]}}}async function n(t,n){try{return{available:!0,...await e(`/api/explain-pattern`,{title:t.title,hypothesis:t.hypothesis,issues:n.map(e=>({title:e.title,category:e.category,address:e.address,status:e.status,reported:e.reportedAt||e.createdAt}))})}}catch(e){return console.warn(`explain-pattern unavailable, using rule text`,e),{available:!1,explanation:t.hypothesis,checks:[t.recommendation],caveats:`Generated from the rule definition because the AI service is offline.`}}}export{n,t};